import{_ as a,a as t,b as n,c as r,d as o,e as i}from"./chunks/m1-m2-roadmap-06.DELWMPzd.js";import{_ as s,o as c,c as l,a2 as h}from"./chunks/framework.CNfFRqmr.js";const y=JSON.parse('{"title":"Benchmarking Beyond Scores: How harness9 Iterates from Execution Traces","description":"","frontmatter":{"title":"Benchmarking Beyond Scores: How harness9 Iterates from Execution Traces","date":"2026-07-24T00:00:00.000Z","tags":["harness9","agent","golang","benchmark","swe-bench","terminal-bench"],"summary":"harness9 treats SWE-bench and Terminal-Bench runs as engineering evidence: it aligns trajectories, patches, environments, and verifier output to improve the runtime rather than merely chase a score.","cover":"/blog/benchmark-driven-iteration/images/cover.png"},"headers":[],"relativePath":"blog/benchmark-driven-iteration/index.md","filePath":"blog/benchmark-driven-iteration/index.md"}'),d={name:"blog/benchmark-driven-iteration/index.md"};function u(m,e,p,b,g,f){return c(),l("div",null,[...e[0]||(e[0]=[h('<h1 id="benchmarking-beyond-scores-how-harness9-iterates-from-execution-traces" tabindex="-1">Benchmarking Beyond Scores: How harness9 Iterates from Execution Traces <a class="header-anchor" href="#benchmarking-beyond-scores-how-harness9-iterates-from-execution-traces" aria-label="Permalink to &quot;Benchmarking Beyond Scores: How harness9 Iterates from Execution Traces&quot;">​</a></h1><h2 id="about-harness9" tabindex="-1">About harness9 <a class="header-anchor" href="#about-harness9" aria-label="Permalink to &quot;About harness9&quot;">​</a></h2><p>harness9 is a Local-First, lightweight, feature-complete, production-ready Agent framework for Go.</p><ul><li><strong>Website</strong>: <a href="https://zhangshenao.github.io/harness9/" target="_blank" rel="noreferrer">https://zhangshenao.github.io/harness9/</a></li><li><strong>GitHub</strong>: <a href="https://github.com/ZhangShenao/harness9" target="_blank" rel="noreferrer">https://github.com/ZhangShenao/harness9</a></li></ul><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>SWE-bench evaluates whether an Agent can turn an issue and a repository revision into a patch that passes hidden tests.</li><li>Terminal-Bench evaluates the final state of a real terminal environment through Harbor and a task verifier.</li><li>A score alone cannot distinguish an engine defect, a broken environment, an adapter constraint, and a model decision.</li><li>harness9 uses trajectory analysis to turn those distinctions into narrowly scoped changes: bootstrap steps, verification gates, retries, timeouts, and stall prompts.</li><li>M1 is the shipped v1.0.0 Agent Harness baseline. M2, a local multi-Agent OS, is a roadmap rather than a benchmark result.</li></ul><p><img src="'+a+'" alt="The benchmark-to-iteration feedback loop"></p><h2 id="swe-bench-patch-quality-without-test-leakage" tabindex="-1">SWE-bench: patch quality without test leakage <a class="header-anchor" href="#swe-bench-patch-quality-without-test-leakage" aria-label="Permalink to &quot;SWE-bench: patch quality without test leakage&quot;">​</a></h2><p>A SWE-bench instance supplies a repository, a base commit, and an issue description. The runner creates an isolated work directory and Sandbox, runs the Agent with normal file and shell tools, then collects the resulting <code>git diff</code>. The official evaluator applies its private <code>test_patch</code> only after the Agent has finished.</p><p>This boundary matters. <code>problem_statement</code> is valid Agent input; <code>test_patch</code>, <code>FAIL_TO_PASS</code>, and <code>PASS_TO_PASS</code> are evaluator-only evidence. Exposing them to the prompt would turn an evaluation into test leakage.</p><p><img src="'+t+'" alt="The SWE-bench execution and evaluation boundary"></p><p>The runner also preserves new files with <code>git add -A -N</code> before collecting the diff. Benchmark execution uses bounded turns, retry policy, an expanded shell timeout, and project bootstrap commands so a recoverable dependency failure does not look like a model failure.</p><h2 id="a-verification-gate-not-an-infinite-loop" tabindex="-1">A verification gate, not an infinite loop <a class="header-anchor" href="#a-verification-gate-not-an-infinite-loop" aria-label="Permalink to &quot;A verification gate, not an infinite loop&quot;">​</a></h2><p>Early trajectories showed a basic failure mode: Agents often stopped without running a real test. <code>runWithVerificationGate</code> observes bash tool events. If a run ends without a detected test command, the benchmark runner injects one verification reminder and resumes with the same <code>MemorySession</code>.</p><p>The continuation is deliberately capped at one attempt and remains bounded by the instance timeout and <code>MaxTurns</code>; it is a measurement guardrail, not a generic change to the Agent loop.</p><p><img src="'+n+'" alt="The one-shot verification gate"></p><h2 id="terminal-bench-final-environment-state" tabindex="-1">Terminal-Bench: final environment state <a class="header-anchor" href="#terminal-bench-final-environment-state" aria-label="Permalink to &quot;Terminal-Bench: final environment state&quot;">​</a></h2><p>Terminal-Bench 2.0 is integrated through <code>benchmarks/terminal_bench/harness9_agent.py</code>. <code>Harness9Agent</code>, a Harbor <code>BaseInstalledAgent</code>, installs the static harness9 binary into the task container, uploads the instruction file, and runs the binary non-interactively. Harbor owns lifecycle and verifier execution; <code>reward.txt</code> records the outcome.</p><p>This exposed different classes of engineering work. Some task images lacked <code>ca-certificates</code>, so HTTPS failed deterministically for static Go binaries; retrying an unavailable trust store is not resilience. The adapter now installs the certificate package. Likewise, the adapter keeps a wide absolute fallback while Harbor respects task-specific timeout budgets.</p><p><img src="'+r+'" alt="The Harbor and Terminal-Bench adapter lifecycle"></p><h2 id="use-trajectories-as-evidence" tabindex="-1">Use trajectories as evidence <a class="header-anchor" href="#use-trajectories-as-evidence" aria-label="Permalink to &quot;Use trajectories as evidence&quot;">​</a></h2><p>Every conclusion needs three aligned records: <code>agent/harness9.log</code> for turns and tool calls, the patch or terminal state for actual behavior, and verifier output for an external judgment. Only then can an apparent regression be classified as a runtime issue, an environment issue, an evaluation-adapter issue, or model behavior.</p><p><img src="'+o+'" alt="Trajectory analysis turns evidence into focused changes"></p><p>On a controlled SWE-bench Lite comparison of 24 instances, resolved tasks rose from 16 to 19 and tasks that ran a real test rose from 1 to 18. The important result is not a single percentage point: it is restoring a test-feedback loop that makes subsequent changes explainable.</p><h2 id="from-m1-to-m2" tabindex="-1">From M1 to M2 <a class="header-anchor" href="#from-m1-to-m2" aria-label="Permalink to &quot;From M1 to M2&quot;">​</a></h2><p>M1, harness9 v1.0.0, established the production-ready Agent Harness baseline: the ReAct engine, providers, tools, Sandbox, permissions, MCP, planning, Skills, Sub-Agents, AutoDev, memory, evaluation, benchmarks, observability, TUI, CLI, and bilingual documentation.</p><p>M2 is the roadmap for a local multi-Agent OS. It covers role and permission boundaries, task graphs and scheduling, worktree-session-sandbox lifecycle, resumable state, conflict-aware file ownership, provenance-aware memory, benchmark regression dashboards, and operator controls. It is explicitly not a claimed delivery or an extrapolation from the benchmark score.</p><p><img src="'+i+'" alt="Delivered M1 versus the planned M2 boundary"></p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Benchmarks become useful when they are treated as a chain of evidence, not a leaderboard number. That discipline is what lets harness9 improve an Agent runtime without confusing accidental wins for product progress.</p>',30)])])}const _=s(d,[["render",u]]);export{y as __pageData,_ as default};
